var CANDIDATES = [[20, 20], [35, 35], [12, 12], [50, 50], [30, 0], [0, 30], [50, 0], [0, 50], [6, 6], [70, 70]];

function trimBefore(b, n) {
    if (n <= 0) return "";
    if (b.length <= n) return b;
    var s = b.substr(b.length - n);
    var k = s.search(/[ \r]/);
    if (k >= 0 && k < s.length - 1) s = s.substr(k + 1);
    return s;
}
function trimAfter(a, n) {
    if (n <= 0) return "";
    if (a.length <= n) return a;
    var s = a.substr(0, n);
    var k = Math.max(s.lastIndexOf(" "), s.lastIndexOf("\r"));
    if (k > 0) s = s.substr(0, k);
    return s;
}
function escFind(s) { return s.replace(/\^/g, "^^").replace(/\r/g, "^p"); }

function findAll(doc, q) {
    app.findTextPreferences = NothingEnum.nothing;
    app.findTextPreferences.findWhat = q;
    return doc.findText();
}

function pageOf(story, pos) {
    try {
        var ip = story.insertionPoints[Math.min(pos, story.insertionPoints.length - 1)];
        var tf = ip.parentTextFrames[0];
        if (tf && tf.parentPage) return tf.parentPage.name;
    } catch (e) {}
    return "overset?";
}

function main() {
    if (app.documents.length == 0) { alert("Apri prima GOLD MAN.indd"); return; }
    var doc = app.activeDocument;
    if (!confirm("Applico fino a " + DATA.length + " correzioni a '" + doc.name + "'.\n\nHai fatto una COPIA di sicurezza del file .indd?\n\nContinuare?")) return;

    app.findTextPreferences = NothingEnum.nothing;
    app.changeTextPreferences = NothingEnum.nothing;
    var o = app.findChangeTextOptions;
    o.caseSensitive = true; o.wholeWord = false; o.includeMasterPages = false;
    o.includeFootnotes = true; o.includeHiddenLayers = false;
    try { o.includeLockedLayersForFind = true; o.includeLockedStoriesForFind = true; } catch (e) {}

    var log = [];
    var jobs = [];

    // FASE 1: localizza tutto prima di modificare qualunque cosa
    for (var i = 0; i < DATA.length; i++) {
        var d = DATA[i];
        var num = d[0], op = d[1], before = d[2], orig = d[3], after = d[4], val = d[5], mp = d[6];
        var found = null, status = "NON TROVATA", sawMany = false;
        for (var c = 0; c < CANDIDATES.length; c++) {
            var b = trimBefore(before, CANDIDATES[c][0]);
            var a = trimAfter(after, CANDIDATES[c][1]);
            if (b.length + a.length < 6 && orig.length < 25) continue;
            var q = b + orig + a;
            if (q.length > 240) continue;
            var res;
            try { res = findAll(doc, escFind(q)); } catch (e) { continue; }
            if (res.length == 1) {
                var st = res[0].parentStory;
                var start = res[0].insertionPoints[0].index;
                found = { story: st, pos: start + b.length, len: orig.length };
                break;
            }
            if (res.length > 1) sawMany = true;
        }
        if (!found) {
            log.push([num, sawMany ? "AMBIGUA (piu' occorrenze)" : "NON TROVATA", mp, "", op, orig, val]);
            continue;
        }
        found.num = num; found.op = op; found.orig = orig; found.val = val; found.mp = mp;
        found.sid = found.story.id;
        found.page = pageOf(found.story, found.pos);
        jobs.push(found);
    }

    // conflitti (correzioni che si sovrappongono)
    // ordine: per brano, dalla fine all'inizio; a parita' di posizione prima le sostituzioni, poi gli inserimenti
    jobs.sort(function (x, y) {
        if (x.sid != y.sid) return x.sid - y.sid;
        if (x.pos != y.pos) return y.pos - x.pos;
        if ((x.len > 0) != (y.len > 0)) return x.len > 0 ? -1 : 1;
        return y.num - x.num;
    });
    var ok = [], styles = [];
    for (var j = 0; j < jobs.length; j++) {
        var J = jobs[j], clash = false;
        if (J.op == "style") { styles.push(J); continue; }   // il corsivo non sposta il testo: nessun conflitto
        for (var k = 0; k < ok.length; k++) {
            var K = ok[k];
            if (K.sid != J.sid) continue;
            var a1 = J.pos, a2 = J.pos + J.len, b1 = K.pos, b2 = K.pos + K.len;
            if ((J.len > 0 && K.len > 0 && a1 < b2 && b1 < a2) ||
                (J.len == 0 && K.len > 0 && a1 > b1 && a1 < b2) ||
                (K.len == 0 && J.len > 0 && b1 > a1 && b1 < a2)) { clash = K.num; break; }
        }
        if (clash) { log.push([J.num, "CONFLITTO con #" + clash + " (stesso punto: verificare a mano)", J.mp, J.page, J.op, J.orig, J.val]); continue; }
        ok.push(J);
    }

    if (USE_TRACK_CHANGES) {
        for (var s = 0; s < doc.stories.length; s++) { try { doc.stories[s].trackChanges = true; } catch (e) {} }
    }

    // FASE 2: prima il corsivo (non cambia le posizioni), poi il testo dal fondo verso l'inizio di ogni brano
    var applied = 0;
    ok = styles.concat(ok);
    for (var m = 0; m < ok.length; m++) {
        var J = ok[m], st = J.story;
        try {
            if (J.len > 0) {
                var rng = st.characters.itemByRange(J.pos, J.pos + J.len - 1);
                var cur = rng.contents;
                if (cur instanceof Array) cur = cur.join("");
                if (String(cur) != J.orig) {
                    log.push([J.num, "SALTATA (testo diverso dal previsto)", J.mp, J.page, J.op, J.orig, J.val]);
                    continue;
                }
                if (J.op == "del") rng.remove();
                else if (J.op == "rep") rng.contents = J.val;
                else if (J.op == "style") rng.fontStyle = J.val;
            } else if (J.op == "ins") {
                st.insertionPoints[J.pos].contents = J.val;
            }
            applied++;
            log.push([J.num, "APPLICATA", J.mp, J.page, J.op, J.orig, J.val]);
        } catch (e) {
            log.push([J.num, "ERRORE: " + e.message, J.mp, J.page, J.op, J.orig, J.val]);
        }
    }

    // log
    log.sort(function (x, y) { return x[0] - y[0]; });
    var folder;
    try { folder = doc.filePath; } catch (e) { folder = Folder.desktop; }
    var f = new File(folder + "/GoldMan_correzioni_log.txt");
    f.encoding = "UTF-8"; f.lineFeed = "Unix"; f.open("w");
    f.writeln("#\tESITO\tPAG. PDF MARKUP\tPAG. INDESIGN\tOPERAZIONE\tTESTO ORIGINALE\tNUOVO");
    var notApplied = [];
    for (var L = 0; L < log.length; L++) {
        var r = log[L];
        f.writeln([r[0], r[1], r[2], r[3], r[4], String(r[5]).replace(/\r/g, " [P] "), String(r[6]).replace(/\r/g, " [P] ")].join("\t"));
        if (r[1] != "APPLICATA") notApplied.push(r[0]);
    }
    f.close();
    app.findTextPreferences = NothingEnum.nothing;

    alert("Fatto.\n\nApplicate: " + applied + " su " + DATA.length +
          "\nDa fare a mano: " + notApplied.length +
          (notApplied.length ? "\n(# " + notApplied.slice(0, 60).join(", ") + (notApplied.length > 60 ? " ..." : "") + ")" : "") +
          "\n\nLog: " + f.fsName +
          "\n\nControlla le modifiche in Editor brani (Cmd+Y) con Revisioni attive." +
          "\nNB: le modifiche di corsivo non compaiono nelle Revisioni: sono nel log.");
}

app.doScript(main, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Correzioni Gold Man round 1");
